import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, Color } from 'three/webgpu';
import { texture, uv, mul, add, mix, float } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {object} NodeConfig
 * @property {string} [imageUrl]
 * @property {string} [depthMapUrl]
 * @property {Array<{name:string,params:any,trigger?:string}>} [cinematicPrimitives]
 * @property {any} [textContent]
 * @property {any} [intent]
 * @property {any} [visualSpec]
 */

/**
 * @typedef {object} NodeContext
 * @property {object} THREE
 * @property {{loadTexture(url:string):Promise<any>}} textureLoader
 * @property {{loadGLB(url:string):Promise<any>}} glbLoader
 * @property {{loadVideo?(url:string):Promise<any>}} videoLoader
 * @property {{createText(content:string, opts?:any):any}} fontAtlas
 * @property {{[key:string]:(target:any, params:any)=>{timeline:any, cleanup:()=>void}}} primitives
 * @property {(event:string, payload:any)=>void} emit
 * @property {string} [tier]
 */

/**
 * Creates the photo‑hero composite node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, Color } = ctx.THREE;

  // Root container
  const root = new Group();

  // ------------------------------------------------------------
  // 1️⃣  Plane with image + depth displacement
  // ------------------------------------------------------------
  const planeWidth = 4.0;
  const planeHeight = 2.5;
  const geometry = new PlaneGeometry(planeWidth, planeHeight, 64, 64);

  // Base material – start transparent, will be faded in
  const material = new MeshStandardNodeMaterial({
    color: new Color('#ffffff'),
    transparent: true,
    opacity: 0,
  });

  // Placeholder textures – will be replaced when loaded
  let imageTex = null;
  let depthTex = null;

  // Load image texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imageTex = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Load depth map texture for displacement
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTex = tex;
      // Use node displacement for finer control
      const uvNode = uv();
      const dispTexNode = texture(depthTex);
      const dispNode = mul(dispTexNode.r, float(0.18)); // scale amplitude
      material.displacementNode = dispNode;
      material.needsUpdate = true;
    });
  }

  // Create mesh
  const planeMesh = new Mesh(geometry, material);
  planeMesh.position.set(0, 0, 0);
  root.add(planeMesh);

  // ------------------------------------------------------------
  // 2️⃣  Caption block (bottom‑left)
  // ------------------------------------------------------------
  const captionGroup = new Group();
  // Padding from bottom‑left
  const pad = 0.5; // 2 × base unit (0.25)
  const startY = -planeHeight / 2 + pad;
  captionGroup.position.set(-planeWidth / 2 + pad, startY, 0.01); // slightly above plane

  // Text items definition (order matters)
  const textItems = [
    {
      role: 'kicker',
      content: 'NOVA ATELIER / GENEVA',
      fontSize: 9,
      color: '#e8ecf2',
      lineHeight: 1.2,
    },
    {
      role: 'headline',
      content: 'Time, Machined.',
      fontSize: 34,
      color: '#e8ecf2',
      lineHeight: 1.1,
    },
    // Accent hairline bar will be inserted after headline
    {
      role: 'body',
      content: 'Every case begins as a single billet of 904L steel.',
      fontSize: 13,
      color: '#e8ecf2',
      lineHeight: 1.5,
    },
    {
      role: 'caption',
      content: 'CALIBRE NA-01 / 72 HOUR RESERVE',
      fontSize: 9,
      color: '#e8ecf2',
      lineHeight: 1.4,
    },
  ];

  // Helper to create text
  function addText(item, yOffset) {
    const txt = ctx.fontAtlas.createText(item.content, {
      fontSize: item.fontSize,
      color: item.color,
      align: 'left',
    });
    txt.position.set(0, yOffset, 0);
    captionGroup.add(txt);
    return txt;
  }

  let cursorY = 0;
  const lineSpacing = 0.25; // baseline rhythm

  // Kicker
  addText(textItems[0], cursorY);
  cursorY -= (textItems[0].fontSize / 100) * lineSpacing * 2; // approximate spacing

  // Headline
  addText(textItems[1], cursorY);
  cursorY -= (textItems[1].fontSize / 100) * lineSpacing * 2;

  // Accent hairline bar
  const barWidth = 0.75; // 0.75 * plane width proportionally
  const barHeight = 0.02;
  const barGeom = new PlaneGeometry(barWidth, barHeight);
  const barMat = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.8,
    transparent: true,
    opacity: 0,
  });
  const barMesh = new Mesh(barGeom, barMat);
  barMesh.position.set(0, cursorY + barHeight / 2, 0);
  captionGroup.add(barMesh);
  // Fade‑in bar together with caption later
  // Keep reference for cleanup
  // No extra offset for bar itself
  cursorY -= (barHeight + lineSpacing * 0.5);

  // Body
  addText(textItems[2], cursorY);
  cursorY -= (textItems[2].fontSize / 100) * lineSpacing * 2;

  // Caption
  addText(textItems[3], cursorY);
  // ------------------------------------------------------------
  // 3️⃣  Bottom scrim gradient (full‑width, thin)
  // ------------------------------------------------------------
  const scrimGeom = new PlaneGeometry(planeWidth, 0.4);
  // Gradient via node material
  const gradMat = new MeshStandardNodeMaterial({
    transparent: true,
    opacity: 1,
    // We'll construct a simple vertical gradient node
  });
  // Gradient nodes
  const vUv = uv();
  const stop0 = float(0.45);
  const stop1 = float(1.0);
  const color0 = new Color('#0b0b1000');
  const color1 = new Color('#0b0b10eb');
  const gradColor = mix(color0, color1, smoothstep(stop0, stop1, vUv.y));
  gradMat.colorNode = gradColor;
  const scrimMesh = new Mesh(scrimGeom, gradMat);
  scrimMesh.position.set(0, -planeHeight / 2 + 0.2, 0.02);
  root.add(scrimMesh);

  // Add caption group after scrim so it appears above
  root.add(captionGroup);

  // ------------------------------------------------------------
  // 4️⃣  Animations (GSAP)
  // ------------------------------------------------------------
  const timelines = [];

  // Plate fade‑in
  const plateTL = gsap.timeline();
  plateTL.to(
    material,
    {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    0
  );
  // Bar fade‑in together with caption
  plateTL.to(
    barMat,
    {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    0
  );
  timelines.push(plateTL);

  // Caption rise‑in
  captionGroup.position.y = 0.4;
  const captionTL = gsap.timeline({ delay: 0.12 });
  captionTL.to(
    captionGroup.position,
    {
      y: 0,
      duration: 0.7,
      ease: 'cubic-bezier(0.215,0.61,0.355,1)',
    },
    0
  );
  timelines.push(captionTL);

  // ------------------------------------------------------------
  // 5️⃣  Cinematic primitives (parallax‑scroll)
  // ------------------------------------------------------------
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (typeof ctx.primitives[prim.name] === 'function') {
        const handle = ctx.primitives[prim.name](root, prim.params || {});
        primitiveHandles.push(handle);
      }
    }
  }

  // ------------------------------------------------------------
  // 6️⃣  Cleanup
  // ------------------------------------------------------------
  root.userData.handlers = {}; // no custom DOM events

  root.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();
    barGeom.dispose();
    barMat.dispose();
    scrimGeom.dispose();
    gradMat.dispose();

    // Dispose loaded textures if they exist
    if (imageTex && imageTex.dispose) imageTex.dispose();
    if (depthTex && depthTex.dispose) depthTex.dispose();

    // Kill GSAP timelines
    for (const tl of timelines) {
      if (tl && tl.kill) tl.kill();
    }

    // Cleanup primitives
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
  };

  return root;
}
